import type { ReactNode, SVGProps } from "react";

import { cn } from "@/shared/lib/cn";

/** Matches `SidebarNavItem` icon slot (16×16). */
export const SIDEBAR_NAV_ICON_CLASS = "size-4 shrink-0";

/** Tabler-derived nav glyphs exported at 13×15 (stroke 1.04). */
const VIEW_BOX = "0 0 13 15";
const STROKE_WIDTH = 1.04;

type SidebarNavIconProps = SVGProps<SVGSVGElement>;

function SidebarNavIcon({
  className,
  children,
  ...props
}: SidebarNavIconProps & { children: ReactNode }) {
  return (
    <svg
      viewBox={VIEW_BOX}
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      role="presentation"
      aria-hidden="true"
      focusable="false"
      className={cn(SIDEBAR_NAV_ICON_CLASS, className)}
      {...props}
    >
      {children}
    </svg>
  );
}

